<?php
function money($n){global $categoryNames;return (jtruth(($n===null))?'Price on request':jadd('AED ',jmethod($n,'toLocaleString','en-AE',['maximumFractionDigits'=>2])));}
function bookUrl($p){global $categoryNames;return jadd('/booking.php?tour=',rawurlencode((jmethod(jmethod(jget($p,'path'),'split','/'),'pop'))));}
function image($p){global $categoryNames;return jmethod(jget($p,'images'),'find',function($x) use ($categoryNames,$p){return validImage(jget($x,'src'));});}
function whatsapp($s,$msg='I would like help with a booking.'){global $categoryNames;
