/\\//','test',$v);}),'map',function($arg0) use ($categoryNames,$s,$pages,$title,$body,$description,$script,$head){[$n,$url]=$arg0;return ('<a href="'.jstr(e($url)).'" target="_blank" rel="noopener noreferrer">'.jstr($n).'</a>');}),'join','')).'</div></div><div><h3>Explore</h3>'.jstr(jmethod(jmethod(jentries($categoryNames),'map',function($arg0) use ($categoryNames,$s,$pages,$title,$body,$description,$script,$head){[$c,$n]=$arg0;return ('<a href="'.jstr((jtruth(($c==='general'))?'/dubai-safari-park-tour':(jtruth(($c==='attractions'))?'/attractions.php':jadd('/category/',$c)))).'">'.jstr($n).'</a>');}),'join','')).'</div><div><h3>Get in touch</h3><a href="tel:'.jstr(e(jmethod(jget($s,'phone'),'replace','/[^+\\d]/g',''))).'">'.jstr(e(jget($s,'phone'))).'</a><a href="mailto:'.jstr(e(jget($s,'email'))).'">'.jstr(e(jget($s,'email'))).'</a><p>'.jstr(e(jget($s,'address'))).'</p><a href="'.jstr(e(whatsapp($s))).'" target="_blank" rel="noopener">Chat on WhatsApp</a></div></div><div class="container footer-bottom"><span>© '.jstr(jmethod(new JDate(),'getFullYear')).' '.jstr(e(jget($s,'name'))).'</span><a href="/blog">Travel guides</a><a href="https://mhitsol.com/" target="_blank" rel="noopener noreferrer">Website Built By: MHIT Solutions</a></div></footer><script src="/site-ui.js" defer></script>'.jstr($script).'</body></html>');
