ari,'title'))).'" loading="lazy"></div><div class="featured-copy"><p class="kicker">THE FEATURED EXPERIENCE</p><h2>'.jstr(e(jget($safari,'title'))).'</h2><p>'.jstr(e(jget((jget($safari,'experience')),'summary'))).'</p><div class="featured-prices">'.jstr(jmethod(jmethod(bookingPackages($safari),'map',function($pkg) use ($categoryNames,$pages,$s,$home,$exps,$safari,$summary){return ('<div><span>'.jstr(e(jget($pkg,'name'))).'</span><strong>'.jstr(money((jtruth(jget($pkg,'adultPrice'))?jget($pkg,'adultPrice'):jget($pkg,'unitPrice')))).'</strong></div>');}),'join','')).'</div><a class="button" href="'.jstr(jget($safari,'path')).'">Explore Safari Park</a><a class="text-link" href="'.jstr(bookUrl($safari)).'">Book this tour</a></div></section>'):'')).''.jstr(jmethod(jmethod(['attractions','desert-safari','city-tours','adventure','luxury'],'map',function($c,$i) use ($categoryNames,$pages,$s,$home,$exps,$safari,$summary){$source=jmethod(jget($home,'html'),'match',jregex(jadd(jadd('<section[^>]*id="',$c),'"[^>]*>[\\s\\S]*?<h2[^>]*>([\\s\\S]*?)<\\/h2>[\\s\\S]*?<p[^>]*>([\\s\\S]*?)<\\/p>')));
